ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2 ImageFileName=/\\(rclone|winscp|filezilla|anydesk|rustdesk|advanced_ip_scanner|netscan|masscan|ngrok|cloudflared)\.exe$/i
| ToolName := lower(ImageFileName)
| case {
    regex("(rclone|winscp|filezilla)\\.exe$", field=ToolName) | Category := "Exfil" ;
    regex("(advanced_ip_scanner|netscan|masscan)\\.exe$", field=ToolName) | Category := "Discovery" ;
    regex("(anydesk|rustdesk|ngrok|cloudflared)\\.exe$", field=ToolName) | Category := "RemoteAccess" ;
    * | Category := "Other" }
| groupBy([aid, ComputerName], function=[count(field=Category, distinct=true, as=categories), collect([ImageFileName, CommandLine])])
| categories >= 2
